  '**الخوارزمية:** 1. افحص جهد الدخل 19V (أو 12V) عند المقاومة PR1 (Current Sensor). 2. تأكد من وجود جهد Standby (3.3V / 5V) على الملفات PL301 و PL302. 3. إذا غاب جهد الـ 3.3V، افحص خرج منظم الجهد LDO في الـ IC المسؤول (PU301). 4. افحص إشارة التشغيل (Power Button Signal) على الـ IO (IT8586E) عند الرجل المسؤولة (عادة PWR_SW#). 5. تأكد من سلامة كريستالة الـ RTC (32.768 KHz).',
  '**الخوارزمية:** 1. افحص جهد الدخل 19V (أو 12V) عند المقاومة PR1 (Current Sensor). 2. تأكد من وجود جهد Standby (3.3V / 5V) على الملفات PL301 و PL302. 3. إذا غاب جهد الـ 3.3V، افحص خرج منظم الجهد LDO في الـ IC المسؤول (PU301). 4. افحص إشارة التشغيل (Power Button Signal) على الـ IO (IT8586E) عند الرجل المسؤولة (عادة PWR_SW#). 5. تأكد من سلامة كريستالة الـ RTC (32.768 KHz).',
